import{_ as i,a0 as n,w as s,s as u,ao as a,I as p,x as o,a1 as r,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"谷歌使用 Duality 主導的完全同態開源加密庫 | LCTT x X-CMD","titleTemplate":false,"description":"谷歌使用 Duality 主導的完全同態開源加密庫 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"谷歌使用 Duality 主導的完全同態開源加密庫 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"谷歌使用 Duality 主導的完全同態開源加密庫 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220914 Google Uses Fully Homomorphic Open Source Duality-Led Encryption Library","title":"谷歌使用 Duality 主導的完全同態開源加密庫","tag":"202209","desc":""},"relativePath":"202209/20220914 Google Uses Fully Homomorphic Open Source Duality-Led Encryption Library.md","filePath":"[post].md"}'),y={name:"202209/20220914 Google Uses Fully Homomorphic Open Source Duality-Led Encryption Library.md"};function d(m,t,f,T,g,D){const e=n("Link");return s(),u("div",null,[t[15]||(t[15]=a('<h1 id="谷歌使用-duality-主導的完全同態開源加密庫" tabindex="-1">谷歌使用 Duality 主導的完全同態開源加密庫 <a class="header-anchor" href="#谷歌使用-duality-主導的完全同態開源加密庫" aria-label="Permalink to “谷歌使用 Duality 主導的完全同態開源加密庫”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/09/google-3-1536x1123.jpg" alt=""></p><blockquote><p>合作伙伴關係的增長加速了 FHE 市場的採用。</p></blockquote><p>據 Duality 技術公司的新聞稿，谷歌已將其在 GitHub 上開源的使用 XLS SDK 開發的開源項目完全同態加密（FHE）轉譯器與領先的開源<ruby>完全同態加密<rt>fully homomorphic encryption</rt></ruby>庫 OpenFHE 合併。通過使加密知識更簡單、更容易接近，開發者對 FHE 的採用將增加。</p><p>這類稱為 FHE 的加密技術不同於更常見的加密技術，因為它可以直接對加密數據進行計算，而無需密鑰。一個由知名密碼學家組成的社區創建了 OpenFHE，這是一個根深於後量子開源晶格密碼學的加密庫。</p><p>該庫旨在實現最佳可用性、增強的 API、模組化、跨平台可移植性，以及與硬件結合時的項目加速器。開發人員可以通過將 OpenFHE 與谷歌的轉譯器結合起來，使用高級代碼來操作加密數據，例如經常用於未加密數據的 C++，而不需要學習密碼學。</p><p>谷歌的轉譯器簡化了使用 FHE 驅動的應用程序的過程，而無需目前從頭開始構建 FHE 所需的廣泛的軟件開發專業知識。這填補了軟件設計人員和開發人員偶爾遇到的空白，他們希望從 FHE 的功能中受益，而不必經歷那具有挑戰性的學習曲線。</p><p>Duality 公司的密碼學研究高級主管兼首席科學家 Yuriy Polyakov 補充説：“我們的團隊通過我們的 OpenFHE 庫達成了重要的里程碑，它已迅速成為當今許多技術領導者的選擇，例如谷歌。谷歌轉譯器為那些非 FHE 專家的應用開發者社區提供了 OpenFHE 同態加密的最新技術。”</p><hr>',9)),p("p",null,[t[1]||(t[1]=o("via: ",-1)),r(e,{href:"https://www.opensourceforu.com/2022/09/google-uses-fully-homomorphic-open-source-duality-led-encryption-library/"},{default:l(()=>[...t[0]||(t[0]=[o("https://www.opensourceforu.com/2022/09/google-uses-fully-homomorphic-open-source-duality-led-encryption-library/",-1)])]),_:1})]),p("p",null,[t[6]||(t[6]=o("作者：",-1)),r(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:l(()=>[...t[2]||(t[2]=[o("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=o(" 選題：",-1)),r(e,{href:"https://github.com/lkxed"},{default:l(()=>[...t[3]||(t[3]=[o("lkxed",-1)])]),_:1}),t[8]||(t[8]=o(" 譯者：",-1)),r(e,{href:"https://github.com/littlebirdnest"},{default:l(()=>[...t[4]||(t[4]=[o("littlebirdnest",-1)])]),_:1}),t[9]||(t[9]=o(" 校對：",-1)),r(e,{href:"https://github.com/wxy"},{default:l(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),p("p",null,[t[12]||(t[12]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原創編譯，",-1)),r(e,{href:"https://linux.cn/"},{default:l(()=>[...t[11]||(t[11]=[o("Linux中國",-1)])]),_:1}),t[14]||(t[14]=o(" 榮譽推出",-1))])])}const H=i(y,[["render",d]]);export{E as __pageData,H as default};
